<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class StoreTransportScheduleRequest extends FormRequest{public function authorize():bool{return$this->user()?->can('transporte.programacion.crear')??false;}public function rules():array{$c=$this->user()->company_id;return['transport_route_id'=>['required',Rule::exists('transport_routes','id')->where(fn($q)=>$q->where('company_id',$c)->where('status','active'))],'name'=>'required|string|max:255','starts_on'=>'required|date','ends_on'=>'required|date|after_or_equal:starts_on','default_start_time'=>'required|date_format:H:i','default_arrival_time'=>'required|date_format:H:i','arrival_next_day'=>'nullable|boolean','service_type'=>['required',Rule::in(array_keys(config('transport.service_types')))],'shift'=>['required',Rule::in(array_keys(config('transport.shifts')))],'vehicle_id'=>['nullable',Rule::exists('transport_vehicles','id')->where(fn($q)=>$q->where('company_id',$c)->where('status','active'))],'driver_id'=>['nullable',Rule::exists('transport_personnel','id')->where(fn($q)=>$q->where('company_id',$c)->where('status','active')->where('is_driver',1))],'monitor_id'=>['nullable',Rule::exists('transport_personnel','id')->where(fn($q)=>$q->where('company_id',$c)->where('status','active')->where('is_monitor',1))],'weekdays'=>'required|array|min:1','weekdays.*'=>'integer|between:1,7|distinct'];}protected function prepareForValidation():void{$this->merge(['arrival_next_day'=>$this->boolean('arrival_next_day')]);}}
